'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today = () => new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Budapest'}).format(new Date());
const norm = s => String(s ?? '').normalize('NFC').replace(/[\u2010\u2011]/g,'-').replace(/\s+/g,' ').trim();
const allItems = [...BANK,...DICTATIONS];
const itemById = new Map(allItems.map(q=>[q.id,q]));
const topicById = new Map(TOPICS.map(t=>[t.id,t]));
const createProfile = (name='Felfedező',grade=5) => ({name,grade,xp:0,stats:{},history:[],days:{},wrong:{}});
let storageOK=true;
let db;
try {db=JSON.parse(localStorage.getItem('betusziget-v1') || 'null');}catch(e){storageOK=false;}
if(!db || db.version!==1 || !db.profiles || !db.profiles[db.active]) db={version:1,active:'default',profiles:{default:createProfile()},reading:false,sound:false};
let view='home',session=null,config={mode:'practice',topic:'all',count:10,challenge:false};
let audio=null,audioToken=0;
function profile(){return db.profiles[db.active];}
function save(){try{localStorage.setItem('betusziget-v1',JSON.stringify(db));}catch(e){storageOK=false;}}
function availableTopics(){return TOPICS.filter(t=>t.grade<=profile().grade);}
function availableItems(mode='practice'){return (mode==='dictation'?DICTATIONS.filter(q=>!q.passage):BANK).filter(q=>q.grade<=profile().grade);}
function mastered(s){return s && (s.dates||[]).length>=3 && s.lastOK===true;}
function topicProgress(id){const list=BANK.filter(q=>q.topic===id);return {total:list.length,done:list.filter(q=>mastered(profile().stats[q.id])).length,seen:list.filter(q=>profile().stats[q.id]?.seen).length};}
function streak(){let n=0;let d=new Date(today()+'T12:00:00Z');if(!profile().days[today()])d.setUTCDate(d.getUTCDate()-1);while(profile().days[d.toISOString().slice(0,10)]){n++;d.setUTCDate(d.getUTCDate()-1);}return n;}
function shuffle(a,rng=Math.random){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function seeded(seed){let h=2166136261;for(const c of seed)h=Math.imul(h^c.charCodeAt(0),16777619);return()=>{h|=0;h=h+0x6D2B79F5|0;let t=Math.imul(h^h>>>15,1|h);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
// Fixed blueprint per grade; randomized items within comparable task groups.
function summaryQueue(grade){
 const topics=TOPICS.filter(t=>t.grade<=grade);
 const groups=topics.map(t=>({topic:t,items:BANK.filter(q=>q.topic===t.id&&q.grade<=grade&&q.type!=='dictation'),quota:1})).filter(g=>g.items.length);
 const current=groups.filter(g=>g.topic.grade===grade),older=groups.filter(g=>g.topic.grade<grade);
 let remaining=40-groups.length,ci=0,oi=0,step=0;
 while(remaining>0){
  const primary=(step++%3!==2||!older.length)?current:older;
  let group=primary===current?current[ci++%current.length]:older[oi++%older.length];
  if(!group||group.quota>=group.items.length)group=groups.find(g=>g.quota<g.items.length);
  if(!group)break;
  group.quota++;remaining--;
 }
 const chosen=[];
 for(const g of groups){
  // Avoid allowing large generated pools to displace all original task formats.
  const pool=g.items,generated=pool.filter(q=>q.id.startsWith('gen-')),original=pool.filter(q=>!q.id.startsWith('gen-'));
  const genCount=generated.length&&original.length?Math.floor(g.quota/2):generated.length?g.quota:0;
  const take=(items,n)=>{
   if(!n)return;
   const ranks={choice:0,word:1,fix:2,order:3};
   const ordered=[...items].sort((a,b)=>(ranks[a.type]??1)-(ranks[b.type]??1)||a.answer.length-b.answer.length||a.id.localeCompare(b.id));
   for(let i=0;i<n;i++){
    const lo=Math.floor(i*ordered.length/n),hi=Math.floor((i+1)*ordered.length/n);
    const part=ordered.slice(lo,hi);if(part.length)chosen.push(shuffle(part)[0]);
   }
  };
  take(original,g.quota-genCount);take(generated,genCount);
 }
 return shuffle(chosen);
}

const examMode=new URLSearchParams(location.search).get('dolgozat');
const examGrade=examMode==='7-56'?7:Number(examMode);
const examMax=examMode==='7-56'?6:examGrade;
const examLink=['5','6','7','8','7-56'].includes(examMode);
const examRound=(new URLSearchParams(location.search).get('kor')||'1').replace(/[^a-zA-Z0-9-]/g,'').slice(0,32)||'1';
const examKey='betusziget-dolgozat-'+examMode+'-20261124'+(examRound==='1'?'':'-'+examRound);
const schoolLabel=examGrade+'. osztály – dolgozat az '+(examMax===5?'5.':'5–'+examMax+'.')+' osztály anyagából';
const SCHOOL_RECEIVER="https://script.google.com/macros/s/AKfycbxhZhH8TIfhuTrEgFhpZhBSlC0QWNmDqEqna3_2PqKpV9oqLQPPlT7OHyv9jDhEoic8/exec"; // A tanári Apps Script /exec URL-je, telepítés után.
function examId(){return globalThis.crypto?.randomUUID?.()||('exam-'+Date.now()+'-'+Math.random().toString(36).slice(2));}
function schoolPayload(s){return {id:s.attemptId,name:s.student,studentClass:s.studentClass,status:s.studentStatus||'Nincs megadva',grade:examGrade,maxGrade:examMax,away:s.away||0,answers:s.results.map(r=>({id:r.id,raw:r.raw,skipped:!!r.skipped}))};}
function sendSchool(){
 const s=session;if(!s?.school||!s.finished||s.sending)return;
 if(!SCHOOL_RECEIVER){toast('A Google-táblázat összekötése még nincs aktiválva.');return;}
 if(s.results.some(r=>typeof r.raw!=='string')){toast('Régebbi dolgozat: hiányoznak a pontos válaszok.');return;}
 s.sending=true;s.sent=false;s.sendError='';examSave();renderResult();
 const frame=document.createElement('iframe');frame.name='schoolReceiver';frame.hidden=true;document.body.appendChild(frame);
 const form=document.createElement('form');form.hidden=true;form.method='POST';form.action=SCHOOL_RECEIVER;form.target=frame.name;
 const input=document.createElement('input');input.name='payload';input.value=JSON.stringify(schoolPayload(s));form.appendChild(input);document.body.appendChild(form);
 let timer;const clean=()=>{clearTimeout(timer);window.removeEventListener('message',receive);form.remove();frame.remove();s.sending=false;};
 const receive=e=>{if(!/^https:\/\/(?:[a-z0-9-]+\.)*googleusercontent\.com$/.test(e.origin)&&e.origin!=='https://script.google.com')return;if(e.data?.id!==s.attemptId)return;clean();if(e.data.ok&&Number.isInteger(e.data.score)&&e.data.score>=0&&e.data.score<=40){s.sent=true;s.serverScore=e.data.score;examSave();}else {s.sendError='Az adatfogadó szerver elutasította a beküldést.';toast('A szerver nem fogadta el a mentést. Szólj a tanárnak!');}renderResult();};
 window.addEventListener('message',receive);timer=setTimeout(()=>{clean();s.sendError='Nem érkezett visszaigazolás a szervertől.';toast('Nincs szerver-visszaigazolás. Próbáld újra!');renderResult();},90000);form.submit();
}
function backupSchool(){const s=session;if(!s?.school||!s.finished)return;const blob=new Blob([JSON.stringify({...schoolPayload(s),status:undefined},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Betusziget-'+s.attemptId+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

function examRead(){try{return JSON.parse(localStorage.getItem(examKey)||'null');}catch(e){return null;}}
function examWrite(x){try{localStorage.setItem(examKey,JSON.stringify(x));return true;}catch(e){return false;}}
function examSave(){if(!session?.school)return true;const s=session;return examWrite({name:s.student,studentClass:s.studentClass,status:s.studentStatus||'Nincs megadva',attemptId:s.attemptId,ids:s.queue.map(q=>q.id),index:s.index,results:s.results.map(r=>({id:r.id,raw:r.raw,exact:r.exact&&!r.skipped,skipped:r.skipped})),finished:s.finished,started:s.started,away:s.away||0,sent:!!s.sent,serverScore:s.serverScore});}
function schoolSetup(){
 const old=examRead();
 if(old&&Array.isArray(old.ids)&&old.ids.length===40&&old.ids.every(id=>itemById.has(id))){
  const queue=old.ids.map(id=>itemById.get(id));session={queue,index:Math.min(old.index,39),results:old.results||[],mode:'summary',label:schoolLabel,school:true,student:old.name,studentClass:old.studentClass||String(examGrade)+'.',studentStatus:old.status||'Nincs megadva',attemptId:old.attemptId||examId(),sent:!!old.sent,serverScore:old.serverScore,started:old.started,away:old.away||0,finished:old.finished,selected:null,ordered:[],submitted:false,hint:false,repair:false,heard:false,challenge:false};
  if(session.finished||session.results.length===40){session.finished=true;view='result';renderResult();return;}
  session.index=session.results.length;view='play';renderQuestion();return;
 }
 view='schoolSetup';shell(`<section class="intro"><div class="card"><h1>${examGrade}. osztály – helyesírási dolgozat</h1><p>Az ${examMax===5?'5.':'5–'+examMax+'.'} osztály teljes anyagából · 40 feladat · 40 pont. A beküldött válasz nem módosítható. A kihagyás 0 pont. Az oldal elhagyását a rendszer jelzi az eredménynél.</p><label class="input-label" for="studentName">Teljes neved</label><input id="studentName" type="text" maxlength="80" autocomplete="off"><label class="input-label" for="studentClass">Osztály</label><input id="studentClass" type="text" maxlength="20" autocomplete="off" required><label class="input-label" for="studentStatus">Melyik igaz rád?</label><select id="studentStatus" required><option value="">Válassz!</option><option value="SNI">SNI</option><option value="BTMN">BTMN</option><option value="Egyik sem">Egyik sem</option></select><p class="tiny">A választ bizalmasan, kizárólag az értékeléshez használjuk.</p><div class="q-actions"><button class="btn" data-action="schoolStart">Dolgozat indítása →</button></div></div></section>`);
}
function schoolStart(){
 const name=$('#studentName')?.value.trim();if(!name){toast('Írd be a teljes neved!');return;}const studentClass=$('#studentClass')?.value.trim();if(!studentClass){toast('Add meg az osztályodat!');return;}const status=$('#studentStatus')?.value;if(!['SNI','BTMN','Egyik sem'].includes(status)){toast('Válassz a lehetőségek közül!');return;}
 if(examRead()){schoolSetup();return;}
 const queue=summaryQueue(examMax);if(queue.length!==40)return;
 const attemptId=examId();if(!examWrite({name,status,studentClass,attemptId,ids:queue.map(q=>q.id),index:0,results:[],finished:false,started:Date.now(),away:0})){toast('A mentés nem működik. Szólj a tanárnak!');return;}
 begin(queue,'summary',schoolLabel,false,{school:true,student:name,studentClass,studentStatus:status,attemptId,away:0});
}
function startSummary(){
 const url=new URL(location.href);
 url.searchParams.set('dolgozat',String(profile().grade));
 url.searchParams.delete('kor');
 url.searchParams.delete('osztaly');
 location.assign(url.href);
}
function renderSummarySetup(){
 shell(`<section class="intro"><button class="back-link" data-action="nav" data-view="home">← Vissza a térképre</button><div class="card"><div class="eyebrow">${profile().grade}. OSZTÁLY · 40 PONT</div><h1>Összefoglaló teszt</h1><p>Minden elérhető témakörből kapsz önállóan, hanganyag nélkül megoldható feladatot. A kérdések sorrendje és válogatása változik.</p><p>Minden helyes válasz 1 pont. Nincs súgó, nincs javítás és nincs megoldókulcs. A végén csak a pontszámodat és a százalékos eredményedet látod. A kihagyott feladat 0 pont.</p><button class="btn" data-action="summaryStart">Teszt indítása →</button></div></section>`);
}
function makeQueue(mode,topic,count,challenge=false,daily=false){
 let pool=availableItems(mode).filter(q=>topic==='all'||q.topic===topic);
 const rng=daily?seeded(today()+profile().grade):Math.random;
 if(mode==='exam' && topic==='all' && profile().grade>=6){
  let chosen=[];const grades=Array.from({length:profile().grade-4},(_,i)=>i+5);
  const geoCount=count>=10?2:1;
  chosen.push(...shuffle(pool.filter(q=>q.topic==='geo'),rng).slice(0,geoCount));
  const remaining=count-chosen.length,rest=Math.max(0,remaining-grades.length),weightSum=grades.length+2;
  const quotas=grades.map(g=>1+Math.floor(rest*(g===profile().grade?3:1)/weightSum));
  let excess=remaining-quotas.reduce((n,v)=>n+v,0);for(let i=grades.length-1;excess>0;i=(i+grades.length-1)%grades.length,excess--)quotas[i]++;
  for(let i=0;i<grades.length;i++)chosen.push(...shuffle(pool.filter(q=>q.grade===grades[i]&&q.topic!=='geo'),rng).slice(0,quotas[i]));
  const ids=new Set(chosen.map(q=>q.id));chosen.push(...shuffle(pool.filter(q=>!ids.has(q.id)),rng).slice(0,Math.max(0,count-chosen.length)));
  return shuffle(chosen,rng).slice(0,count);
 }
 if(mode==='practice'&&!daily){
  // A hibás és még nem biztos feladatok előbbre kerülnek, de a körön belül nincs ismétlés.
  pool=shuffle(pool,rng).map(q=>({q,priority:profile().wrong[q.id]?3:!profile().stats[q.id]?2:mastered(profile().stats[q.id])?0:1})).sort((a,b)=>b.priority-a.priority).map(x=>x.q);
 }else pool=shuffle(pool,rng);
 return pool.slice(0,count);
}
function distance(a,b){let prev=Array.from({length:b.length+1},(_,j)=>j);for(let i=1;i<=a.length;i++){let row=[i];for(let j=1;j<=b.length;j++)row[j]=Math.min(row[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));prev=row;}return prev[b.length];}
function fullSentence(q){return q.type==='fix'||q.type==='dictation'||['date-009','date-010','sim7-001'].includes(q.id);}
function answerInstruction(q){
 if(q.type==='order')return 'Rendezd sorrendbe a szavakat!';
 if(isChoice(q))return 'Válaszd ki a helyes választ!';
 if(fullSentence(q))return 'A teljes mondatot írd le! A kijelentő mondat végén a pont elhagyható; a kérdőjel és a felkiáltójel kötelező.';
 if(q.topic==='date'||['sim5-003','sim5-004','sim6-008'].includes(q.id))return 'Csak a kért dátumot vagy alakot írd be!';
 if(/\s/.test(q.answer))return 'Csak a kért teljes szókapcsolatot vagy nevet írd be, ne a mondatot!';
 if(q.type==='word'&&/^\d+[.]?$/.test(q.answer))return 'Csak a kért számot írd be, a szükséges írásjellel!';
 return 'Csak a kért szót vagy alakot írd be, ne a teljes mondatot!';
}
function assess(q,input){
 const actual=norm(input),models=[q.answer,...(q.accepted||[])].map(norm);
 const optionalDot=session?.mode==='summary'&&fullSentence(q);const exact=models.some(m=>m===actual||(optionalDot&&m.endsWith('.')&&!m.endsWith('...')&&actual===m.slice(0,-1)));
 const expected=exact?actual:models.reduce((a,b)=>distance(actual,b)<distance(actual,a)?b:a,models[0]);
 const words=s=>s.match(/[\p{L}\p{N}]+(?:[-–][\p{L}\p{N}]+)*/gu)||[];
 const expectedWords=words(expected),actualWords=words(actual);
 const wordErrors=distance(expectedWords,actualWords);
 const wordCorrect=Math.max(0,expectedWords.length-wordErrors);
 return {exact,actual,expected,wordCorrect,wordTotal:expectedWords.length,wordErrors};
}
function correctDiff(actual,expected){
 const a=Array.from(norm(actual)),b=Array.from(norm(expected));
 const d=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));
 for(let i=0;i<=a.length;i++)d[i][0]=i;for(let j=0;j<=b.length;j++)d[0][j]=j;
 for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));
 let i=a.length,j=b.length,out=[];
 while(i||j){if(i&&j&&d[i][j]===d[i-1][j-1]+(a[i-1]===b[j-1]?0:1)){out.push({c:b[j-1],bad:a[i-1]!==b[j-1]});i--;j--;}else if(j&&d[i][j]===d[i][j-1]+1){out.push({c:b[j-1],bad:true});j--;}else{i--;}}
 return out.reverse().map(x=>x.bad?'<mark>'+esc(x.c===' '?'␣':x.c)+'</mark>':esc(x.c)).join('');
}
